#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>

int& elegir(std::array<int, 2>& datos, int indice) {
    if (indice < 0 || indice > 1) {
        throw std::out_of_range("indice");
    }
    return datos.at(static_cast<std::size_t>(indice));
}

int main() {
    std::array<int, 2> datos{2, 4};
    elegir(datos, 1) = 7;
    std::cout << datos[0] << ':' << datos[1] << ':';
    try {
        elegir(datos, -1) = 9;
    } catch (const std::out_of_range&) {
        std::cout << "Fuera";
    }
    std::cout << ':' << datos[0] << ':' << datos[1];
    return 0;
}

