#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>

int seleccionar(std::array<int, 3>& datos, int indice) {
    if (indice < 0 || indice > 2) {
        throw std::out_of_range("indice");
    }
    return datos.at(static_cast<std::size_t>(indice));
}

int consultar(const std::array<int, 3>& datos, int indice) {
    if (indice < 0 || indice > 2) {
        throw std::out_of_range("indice");
    }
    return datos.at(static_cast<std::size_t>(indice));
}

int main() {
    std::array<int, 3> datos{2, 5, 8};
    const int& vista = consultar(datos, 1);
    const int copia = consultar(datos, 1);
    int cantidad = 0;
    if (!(std::cin >> cantidad) || cantidad < 1 || cantidad > 12) {
        return 1;
    }
    for (int orden = 0; orden < cantidad; ++orden) {
        int indice = 0;
        int valor = 0;
        if (!(std::cin >> indice >> valor)) {
            return 1;
        }
        try {
            int& destino = seleccionar(datos, indice);
            if (valor < 0 || valor > 9) {
                std::cout << "Rechazo";
            } else {
                destino = valor;
                std::cout << "Cambio";
            }
            std::cout << ";Valor:" << destino;
        } catch (const std::out_of_range&) {
            std::cout << "Indice invalido;Valor:-1";
        }
        std::cout << ";Vista:" << vista << ";Copia:" << copia
                  << ";Datos:" << datos[0] << ',' << datos[1] << ',' << datos[2] << '\n';
    }
    return 0;
}

